<?= $this->extend('layouts/main') ?>
<?= $this->section('content') ?>
<section class="wrap products-section"><h1>Your addresses</h1><?php if ($errors = session('errors')): ?><div role="alert"><?php foreach ($errors as $error): ?><p><?= esc($error) ?></p><?php endforeach ?></div><?php endif ?>
<?php foreach ($addresses as $address): ?><article class="cart-item"><div><h2><?= esc($address['recipient_name']) ?></h2><p><?= esc($address['address']) ?>, <?= esc($address['city']) ?>, <?= esc($address['province']) ?> <?= esc($address['postal_code']) ?></p></div><details><summary>Edit address</summary><form class="account-form" action="<?= site_url('account/addresses/' . $address['id'] . '/update') ?>" method="post"><?= csrf_field() ?><?php foreach (['recipient_name' => 'Recipient name', 'phone' => 'Phone', 'address' => 'Street address', 'city' => 'City', 'province' => 'Province', 'postal_code' => 'Postal code'] as $field => $label): ?><label><?= esc($label) ?><input name="<?= esc($field) ?>" value="<?= esc($address[$field]) ?>" required></label><?php endforeach ?><button type="submit">Save changes</button></form></details><form action="<?= site_url('account/addresses/' . $address['id'] . '/default') ?>" method="post"><?= csrf_field() ?><button type="submit"><?= $address['is_default'] ? 'Default address' : 'Set as default' ?></button></form><form action="<?= site_url('account/addresses/' . $address['id'] . '/delete') ?>" method="post"><?= csrf_field() ?><button type="submit">Remove</button></form></article><?php endforeach ?>
<h2>Add an address</h2><form class="account-form" action="<?= site_url('account/addresses') ?>" method="post"><?= csrf_field() ?>
<?php foreach (['recipient_name' => 'Recipient name', 'phone' => 'Phone', 'address' => 'Street address', 'city' => 'City', 'province' => 'Province', 'postal_code' => 'Postal code'] as $name => $label): ?><label for="<?= esc($name) ?>"><?= esc($label) ?></label><input id="<?= esc($name) ?>" name="<?= esc($name) ?>" value="<?= esc(old($name)) ?>" required><?php endforeach ?><button class="button button-dark" type="submit">Save address</button></form></section>
<?= $this->endSection() ?>
